// Adds the duplicate-payment check and decides the final status.
const inv = $('Extracted Invoice').first().json;
const dup = $input.first().json;
const issues = [...inv.issues];
if (dup.id) issues.push(`Invoice number ${inv.invoice_number} from this vendor is already registered (invoice id ${dup.id}): possible duplicate payment`);
return [{ json: { ...inv, issues, status: issues.length ? 'needs_review' : 'approved' } }];
